fn write_consumer(args: &[String], source: &str) -> Result<()> {
    let output = required_path(args, "--output")?;
    if let Some(parent) = output.parent() {
        fs::create_dir_all(parent)?;
    }
    fs::write(output, source)?;
    Ok(())
}

